	/**
	 * Checks whether a quota/rate-limit info has crossed a new threshold
	 * that hasn't been shown yet. Clears stale thresholds when usage drops.
	 *
	 * The first data arrival establishes a baseline: any thresholds already
	 * exceeded at that point are recorded as shown without returning a warning,
	 * so no notification fires for usage that was already over the line. Only
	 * later crossings (below → at/above) after the baseline trigger warnings.
	 */
	private _checkThreshold(info: IChatQuota | undefined, shownThresholds: Set<number>, baseline: { established: boolean }): { percentUsed: number; resetDate: Date } | undefined {
		if (!info) {
			shownThresholds.clear();
			baseline.established = false;
			return undefined;
		}
		if (info.unlimited) {
			return undefined;
		}

		const percentUsed = 100 - info.percentRemaining;

		// Clear thresholds that are no longer crossed (usage dropped)
		for (const threshold of shownThresholds) {
			if (percentUsed < threshold) {
				shownThresholds.delete(threshold);
			}
		}

		// First data arrival: record already-crossed thresholds as the baseline
		// without notifying, even if usage already exceeds one or more thresholds.
		if (!baseline.established) {
			baseline.established = true;
			for (const threshold of THRESHOLDS) {
				if (percentUsed >= threshold) {
					shownThresholds.add(threshold);
				}
			}
			return undefined;
		}

		// Walk thresholds highest-first so we report the most severe crossed threshold
		for (let i = THRESHOLDS.length - 1; i >= 0; i--) {
			const threshold = THRESHOLDS[i];
			if (percentUsed >= threshold && !shownThresholds.has(threshold)) {
				// Mark this and all lower thresholds as shown
				for (let j = 0; j <= i; j++) {
					shownThresholds.add(THRESHOLDS[j]);
				}
				return { percentUsed: Math.floor(percentUsed), resetDate: info.resetDate };
			}
		}
		return undefined;
	}

